 protected void updateInventTableModule()
{
    next updateInventTableModule();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        Set priceHistoryRecId = new Set(Types::Int64);

        McrPriceHistoryLine_Sales mcrSalesPriceHistoryLine = this.mcrPriceHistoryLine as McrPriceHistoryLine_Sales;

        MCRPriceHistoryRef mcrPriceHistoryRef;
        MCRPriceHistory mcrPriceHistory;

        while select RecId from mcrPriceHistoryRef
            where mcrPriceHistoryRef.MCROrderLine2PriceHistoryRef == mcrSalesPriceHistoryLine.parmMCROrderLine2PriceHistoryRef()
            join RecId from mcrPriceHistory
                where mcrPriceHistoryRef.PriceHistoryRecId == mcrPriceHistory.RecId
                    && mcrPriceHistory.PriceHistoryType     != MCRPriceHistoryType::MultiLineDisc
        {
            priceHistoryRecId.add(mcrPriceHistory.RecId);
        }

        this.setFoundPriceHistoryRecId = priceHistoryRecId;
    }
}
